module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    logic q1, q2, q3;

    // D flip-flops with synchronous reset (initialized to zero)
    always_ff @(posedge clk) begin
        q1 <= q1;  // placeholder, will be driven by logic below
        q2 <= q2;
        q3 <= q3;
    end

    // Combinational logic for D flip-flop inputs
    // The specification implies the flip-flops store the previous state
    // and the "input" to each D flip-flop is derived from x and its own output.
    // To satisfy the "initially reset to zero" and functional behavior,
    // we infer the next state as follows:
    // D1 = x XOR q1  (XOR gate with second input being its own output)
    // D2 = x AND ~q2  (AND gate with second input being complemented output)
    // D3 = x OR ~q3   (OR gate with second input being complemented output)

    always_comb begin
        // D flip-flop 1: XOR gate. Second input is q1 (its own output).
        // The specification says: "the second input of the XOR is its corresponding flip-flop's output".
        // This creates a feedback loop: D1 = x XOR q1.
        // However, for a stable implementation and to avoid latch inference,
        // we define the next state based on current q values.
        // Given the reset-to-zero assumption and typical FSM intent,
        // we model the D input as x XOR q1.
        q1 <= x ^ q1;  // Note: This toggles when x=1, holds when x=0.

        // D flip-flop 2: AND gate. Second input is complemented output ~q2.
        q2 <= x & ~q2;

        // D flip-flop 3: OR gate. Second input is complemented output ~q3.
        q3 <= x | ~q3;
    end

    // Three-input NOR gate: output Z = ~(q1 | q2 | q3)
    assign z = ~(q1 | q2 | q3);

endmodule

