module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  [9:0] state,
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // One-hot encoded state bits (active high)
    wire S_bit       = state[0];
    wire S1_bit      = state[1];
    wire S11_bit     = state[2];
    wire S110_bit    = state[3];
    wire B0_bit      = state[4];
    wire B1_bit      = state[5];
    wire B2_bit      = state[6];
    wire B3_bit      = state[7];
    wire Count_bit   = state[8];
    wire Wait_bit    = state[9];

    // ---------- Next-state signals (one-hot asserts) ----------
    // S_next: next state is S
    assign S_next = (!d & S_bit) |
                    (!d & S1_bit) |
                    (!d & S110_bit);

    // S1_next: next state is S1
    assign S1_next = (d & S1_bit) |
                     (d & S11_bit);

    // B3_next: next state is B3
    assign B3_next = (d & B3_bit);

    // Count_next: next state is Count
    assign Count_next = (d & B2_bit);

    // Wait_next: next state is Wait
    assign Wait_next = (d & Count_bit & done_counting);

    // ---------- Output logic (Moore machine) ----------
    // shift_ena: asserted in B0, B1, B2, B3
    assign shift_ena = B0_bit | B1_bit | B2_bit | B3_bit;

    // counting: asserted in Count state
    assign counting = Count_bit;

    // done: asserted in Wait state
    assign done = Wait_bit;

endmodule

