module TopModule (
    input  logic clk,
    input  logic resetn,
    input  logic x,
    input  logic y,
    output logic f,
    output logic g
);

    // State encoding: 3 bits are sufficient for the required states
    typedef enum logic [2:0] {
        S_A   = 3'b000,  // Initial/reset state
        S_B   = 3'b001,  // f=1 pulse state
        S_C   = 3'b010,  // Detecting x pattern 1,0,1
        S_D   = 3'b011,  // g=1 asserted, waiting for y
        S_E   = 3'b100,  // g=1 maintained permanently
        S_F   = 3'b101   // g=0 permanently
    } state_t;

    state_t state, next_state;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            S_A:    next_state = S_B;
            S_B:    next_state = S_C;
            S_C:    if (x == 1'b1)
                        next_state = S_D;  // x=1 received, now expecting y
                      else
                        next_state = S_C;  // stay in S_C until x=1
            S_D:    if (y == 1'b1)
                        next_state = S_E;  // y=1 within 2 cycles -> g=1 forever
                      else
                        next_state = S_F;  // y never 1 within 2 cycles -> g=0 forever
            S_E:    next_state = S_E;  // stay in S_E (g=1 maintained)
            S_F:    next_state = S_F;  // stay in S_F (g=0 maintained)
            default: next_state = S_A;
        endcase
    end

    // Output logic (combinational)
    always_comb begin
        case (state)
            S_A:    {f, g} = 2'b00;
            S_B:    {f, g} = 2'b10;  // f=1 for one cycle
            S_C:    {f, g} = 2'b00;
            S_D:    {f, g} = 2'b01;  // g=1 asserted, waiting for y
            S_E:    {f, g} = 2'b01;  // g=1 maintained
            S_F:    {f, g} = 2'b00;  // g=0 permanently
            default:{f, g} = 2'b00;
        endcase
    end

    // State flip-flops (positive-edge triggered, synchronous active-low reset)
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= S_A;
        end else begin
            state <= next_state;
        end
    end

endmodule

