module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Byte shift register: holds the last 3 received bytes
    // byte_reg[2] = most recent, byte_reg[1] = middle, byte_reg[0] = oldest
    logic [7:0] byte_reg [2:0];

    // FSM state transition logic (combinational)
    always_comb begin
        case (state)
            IDLE: begin
                // Look for a byte with bit 3 set
                if (in[3]) begin
                    next_state = BYTE1;
                end else begin
                    next_state = IDLE;
                end
            end
            BYTE1: begin
                // Received first byte, shift in and go to BYTE2
                next_state = BYTE2;
            end
            BYTE2: begin
                // Received second byte, shift in and go to BYTE3
                next_state = BYTE3;
            end
            BYTE3: begin
                // Received third byte, done, go back to IDLE
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // FSM sequential logic (positive edge triggered, synchronous reset)
    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= IDLE;
            byte_reg[0] <= 8'h00;
            byte_reg[1] <= 8'h00;
            byte_reg[2] <= 8'h00;
            done      <= 1'b0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    // In IDLE, we only shift in if we detect byte 1
                    if (in[3]) begin
                        byte_reg[0] <= in;
                        done        <= 1'b0;
                    end else begin
                        byte_reg[0] <= byte_reg[0]; // hold
                        done        <= 1'b0;
                    end
                end
                BYTE1: begin
                    // Shift: old byte0 -> byte1, new in -> byte0
                    byte_reg[0] <= in;
                    byte_reg[1] <= byte_reg[0];
                    byte_reg[2] <= byte_reg[1];
                    done        <= 1'b0;
                end
                BYTE2: begin
                    // Shift: old byte1 -> byte2, old byte0 -> byte1, new in -> byte0
                    byte_reg[0] <= in;
                    byte_reg[1] <= byte_reg[0];
                    byte_reg[2] <= byte_reg[1];
                    done        <= 1'b0;
                end
                BYTE3: begin
                    // Shift: old byte2 -> byte3 (out), old byte1 -> byte2, old byte0 -> byte1, new in -> byte0
                    byte_reg[0] <= in;
                    byte_reg[1] <= byte_reg[0];
                    byte_reg[2] <= byte_reg[1];
                    // Output the 24-bit message (byte_reg[2] is first byte, byte_reg[0] is third byte)
                    out_bytes <= {byte_reg[2], byte_reg[1], byte_reg[0]};
                    done      <= 1'b1;
                end
                default: begin
                    done <= 1'b0;
                end
            endcase
        end
    end

endmodule

