    logic a1_out, b1_out, a2_out, b2_out;

    // First A submodule: z = (x ^ y) & x
    A a1 (
        .x(x),
        .y(y),
        .z(a1_out)
    );

    // First B submodule
    B b1 (
        .x(x),
        .y(y),
        .z(b1_out)
