module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output logic fr2,
    output logic fr1,
    output logic fr0,
    output logic dfr
);

    // Internal state: previous sensor change level (2'b00 = low, 2'b01 = middle, 2'b10 = high)
    // 2'b11 is unused/reserved
    reg [1:0] prev_level;

    // Combinational logic for outputs based on current sensors and previous level
    always @(*) begin
        // Default assignments (all outputs 0)
        fr0 = 1'b0;
        fr1 = 1'b0;
        fr2 = 1'b0;
        dfr = 1'b0;

        // 1. If water level is above the highest sensor s[2]
        if (s[2]) begin
            // No nominal flow inputs asserted
            // dfr stays 0
        end
        // 2. If water level is below the lowest sensor s[0]
        else if (!s[0]) begin
            // Maximum flow rate: all four outputs asserted
            fr0 = 1'b1;
            fr1 = 1'b1;
            fr2 = 1'b1;
            dfr = 1'b1;
        end
        // 3. If water level is between s[2] and s[1] (s[1] asserted, s[2] not asserted, s[0] asserted)
        else if (s[1] && !s[2]) begin
            // Nominal flow rate input fr0 asserted
            fr0 = 1'b1;
        end
        // 4. If water level is between s[1] and s[0] (s[0] asserted, s[1] not asserted)
        else if (s[0] && !s[1]) begin
            // Nominal flow rate inputs fr0 and fr1 asserted
            fr0 = 1'b1;
            fr1 = 1'b1;
        end
    end

    // Sequential logic for previous level state
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Active-high synchronous reset: sets state to equivalent of long low water level
            // "no sensors asserted, and all four outputs asserted"
            // This means prev_level should be set to the state representing "Below s[0]"
            // Below s[0] corresponds to prev_level = 2'b00 (low)
            prev_level <= 2'b00;
        end
        else begin
            // Update previous level based on current sensor state
            // Logic: determine the current operating region and store it
            if (s[2]) begin
                // Above highest sensor
                prev_level <= 2'b10; // high
            end
            else if (!s[0]) begin
                // Below lowest sensor
                prev_level <= 2'b00; // low
            end
            else if (s[1] && !s[2]) begin
                // Between upper and middle
                prev_level <= 2'b01; // middle
            end
            else if (s[0] && !s[1]) begin
                // Between middle and lower
                prev_level <= 2'b01; // middle (or could be specific, but 01 covers the transition from lower)
            end
            else begin
                // Default case (should not happen with valid sensor encoding, but keep state)
                prev_level <= prev_level;
            end
        end
    end

    // Logic for dfr (Supplemental flow valve) based on level change
    // The specification says: "If the sensor change indicates that the previous level was lower than the current level, 
    // the flow rate should be increased by opening the Supplemental flow valve (controlled by dfr)."
    // We determine current level sense from s and compare with prev_level.
    // Current level encoding: 2'b00=low, 2'b01=middle-low, 2'b10=high
    // (Middle-high between s[2] and s[1] maps to 2'b01 in prev_level logic, but for dfr we compare rise/fall.
    // A rise is detected when current level is higher than previous level.)

    // Assign dfr based on comparison of current level and previous level
    always @(*) begin
        // Current level sense derivation from s
        // Level 0 (Low): !s[0]
        // Level 1 (Lower middle): s[0] && !s[1]
        // Level 2 (Upper middle / between s[2] and s[1]): s[1] && !s[2]
        // Level 3 (High): s[2]
        // We map these to 2-bit values for comparison: 00, 01, 10 (11 unused)
        reg [1:0] current_level;
        if (s[2]) begin
            current_level = 2'b10; // High
        end
        else if (s[1] && !s[2]) begin
            current_level = 2'b01; // Upper middle
        end
        else if (s[0] && !s[1]) begin
            current_level = 2'b01; // Lower middle (treated as middle for level change detection per spec flow)
        end
        else begin
            current_level = 2'b00; // Low
        end

        // dfr is 1 if current level > previous level (rise detected)
        // Comparison: current_level > prev_level
        // Since values are 00, 01, 10, standard unsigned comparison works.
        if (current_level > prev_level) begin
            dfr = 1'b1;
        end
        else begin
            dfr = 1'b0;
        end
    end

endmodule

